import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { QuestionType } from '../generated/graphql';
import { Plus, Trash, GripVertical } from 'lucide-react';
import { QuestionDraft } from '../hooks/useFormBuilder';

interface Props {
  q: QuestionDraft;
  onUpdate: (id: string, updates: Partial<QuestionDraft>) => void;
  onRemove: (id: string) => void;
  onAddOption: (id: string) => void;
  onUpdateOption: (qId: string, oIndex: number, val: string) => void;
  onRemoveOption: (qId: string, oIndex: number) => void;
}

const QuestionItem: React.FC<Props> = ({
  q,
  onUpdate,
  onRemove,
  onAddOption,
  onUpdateOption,
  onRemoveOption,
}) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: q.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : 'auto',
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="bg-white p-6 rounded-lg shadow-md mb-6 border-l-4 border-blue-500 group relative"
    >
      <div
        {...attributes}
        {...listeners}
        className="absolute left-1/2 -top-3 -translate-x-1/2 bg-white border rounded p-1 cursor-grab active:cursor-grabbing opacity-0 group-hover:opacity-100 transition-opacity"
      >
        <GripVertical className="w-4 h-4 text-gray-400" />
      </div>

      <div className="flex gap-4 mb-4">
        <input
          type="text"
          placeholder="Question Title"
          className="flex-1 text-xl font-semibold border-b outline-none p-2 focus:border-blue-500"
          value={q.title}
          onChange={(e) => onUpdate(q.id, { title: e.target.value })}
        />
        <select
          className="border p-2 rounded bg-gray-50"
          value={q.type}
          onChange={(e) => onUpdate(q.id, { type: e.target.value as QuestionType })}
        >
          <option value={QuestionType.Text}>Text</option>
          <option value={QuestionType.MultipleChoice}>Multiple Choice</option>
          <option value={QuestionType.Checkbox}>Checkbox</option>
          <option value={QuestionType.Date}>Date</option>
        </select>
      </div>

      {(q.type === QuestionType.MultipleChoice || q.type === QuestionType.Checkbox) && (
        <div className="ml-4 space-y-2 mb-4">
          {q.options.map((opt, oIndex) => (
            <div key={oIndex} className="flex items-center gap-2">
              <div
                className={
                  q.type === QuestionType.MultipleChoice
                    ? 'w-4 h-4 rounded-full border'
                    : 'w-4 h-4 border'
                }
              />
              <input
                type="text"
                placeholder={`Option ${oIndex + 1}`}
                className="border-b outline-none p-1 flex-1 focus:border-blue-500"
                value={opt}
                onChange={(e) => onUpdateOption(q.id, oIndex, e.target.value)}
              />
              <button
                type="button"
                onClick={() => onRemoveOption(q.id, oIndex)}
                className="p-1 hover:bg-red-50 rounded"
              >
                <Trash className="w-4 h-4 text-gray-400 hover:text-red-500" />
              </button>
            </div>
          ))}
          <button
            type="button"
            onClick={() => onAddOption(q.id)}
            className="text-blue-600 text-sm hover:underline flex items-center gap-1 mt-2"
          >
            <Plus className="w-4 h-4" /> Add Option
          </button>
        </div>
      )}

      <div className="flex justify-end gap-6 border-t pt-4">
        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            className="w-4 h-4 text-blue-600"
            checked={q.required}
            onChange={(e) => onUpdate(q.id, { required: e.target.checked })}
          />
          <span className="text-sm text-gray-600">Required</span>
        </label>
        <button
          type="button"
          onClick={() => onRemove(q.id)}
          className="p-1 hover:bg-red-50 rounded text-gray-500 hover:text-red-500 transition-colors"
        >
          <Trash className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
};

export default QuestionItem;
